import { useLayoutEffect, useRef, type ReactNode } from 'react';
import '../styles/morse-app.css';
import { PUNCH, rxShift, type TapeGroup } from '../lib/morse-tape';

/* Two phones running the real Morse interface: the markup and class names
 * are the app's own, styled by its stylesheet (src/styles/morse-app.css,
 * generated by scripts/sync-morse-ui.py). Each screen renders at the app's
 * phone width, 390px, and is scaled to fit its frame. */

const APP_W = 390;

/** Scales a 390px-wide app screen to whatever width its frame has. */
function Screen({ attrs, children }: { attrs: Record<string, string | undefined>; children: ReactNode }) {
  const fit = useRef<HTMLDivElement>(null);
  const app = useRef<HTMLDivElement>(null);
  useLayoutEffect(() => {
    const box = fit.current;
    const inner = app.current;
    if (!box || !inner) return;
    const size = () => {
      const k = box.clientWidth / APP_W;
      inner.style.transform = `scale(${k})`;
      inner.style.height = `${box.clientHeight / k}px`;
    };
    size();
    const ro = new ResizeObserver(size);
    ro.observe(box);
    return () => ro.disconnect();
  }, []);
  return (
    <div className="mapp-fit" ref={fit}>
      <div className="mapp" ref={app} {...attrs}>{children}</div>
    </div>
  );
}

function Nameplate({ mode }: { mode: 'broadcast' | 'receive' }) {
  return (
    <header className="plate nameplate">
      <div className="brand"><span className="brand-mark" /><p className="name-title">MORSE</p></div>
      <section className="bay bay-mode">
        <div className="mode-field">
          <div className="mode-lever">
            <input className="mode-radio" type="radio" value="BROADCAST" checked={mode === 'broadcast'} readOnly tabIndex={-1} />
            <span className="key mode-key"><span className="mode-name">BROADCAST</span></span>
            <input className="mode-radio" type="radio" value="RECEIVE" checked={mode === 'receive'} readOnly tabIndex={-1} />
            <span className="key mode-key"><span className="mode-name">RECEIVE</span></span>
          </div>
        </div>
      </section>
      <span className="key menu-key">
        <svg viewBox="0 0 24 24" width="20" height="20">
          <path d="M4 7h9M19 7h1M4 12h3M13 12h7M4 17h9M19 17h1" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
          <circle cx="16" cy="7" r="2.2" fill="none" stroke="currentColor" strokeWidth="2" />
          <circle cx="10" cy="12" r="2.2" fill="none" stroke="currentColor" strokeWidth="2" />
          <circle cx="16" cy="17" r="2.2" fill="none" stroke="currentColor" strokeWidth="2" />
        </svg>
      </span>
    </header>
  );
}

function Head() {
  return (
    <div className="tape-head">
      <span className="head-cap" />
      <span className="head-rail head-rail-l" />
      <span className="head-rail head-rail-r" />
      <span className="head-slot" />
      <span className="head-lamp" />
    </div>
  );
}

function Group({ g, cls, marks = g.code }: { g: TapeGroup; cls: string; marks?: string }) {
  const width = marks === g.code ? g.width
    : [...marks].reduce((w, s) => w + (s === '.' ? PUNCH.dot : PUNCH.dash), 0) + Math.max(0, marks.length - 1) * PUNCH.gap;
  return (
    <li className={cls} style={{ left: g.left, width }}>
      <span className="tg-char">{marks === g.code ? g.char : ''}</span>
      <span className="tg-marks">
        {[...marks].map((s, i) => <span key={i} className={s === '.' ? 'tp tp-dot' : 'tp tp-dash'} />)}
      </span>
    </li>
  );
}

function Dock({ right }: { right: ReactNode }) {
  return (
    <nav className="dock">
      <span className="key dock-key"><span className="dock-glyph"><i /><b /><i /></span><span className="dock-name">TRANSLATE</span></span>
      <span className="key dock-key">{right}</span>
    </nav>
  );
}

export interface SenderView {
  state: 'idle' | 'broadcasting' | 'done';
  text: string;
  groups: TapeGroup[];
  letter: number;
  mark: number;
  marks: number;
  fire: number;
  seconds: number;
  wpm: number;
  sent: string;
}

export function SenderScreen({ v }: { v: SenderView }) {
  const head = v.groups[Math.max(0, v.letter)];
  const live = v.state === 'broadcasting';
  return (
    <Screen attrs={{ 'data-state': v.state, 'data-mode': 'broadcast', className: `mapp${v.fire ? (v.fire % 2 ? ' fire-a' : ' fire-b') : ''}` }}>
      <Nameplate mode="broadcast" />
      <main className="deck">
        <section className="bay" data-id="composer">
          <div className="composer-head">
            <span className="legend">YOUR MESSAGE</span>
            <output data-id="message-duration">{v.seconds ? `${v.seconds}s TO SEND` : ''}</output>
          </div>
          <textarea className="message-input" rows={1} value={v.text} readOnly tabIndex={-1} disabled={v.state !== 'idle'} />
        </section>
        <section className="bay bay-station" data-id="station">
          <div className="tape-window">
            <div className="tape-inset">
              <Head />
              <ol className="tape-strip" style={{ ['--strip-shift' as string]: `${head ? head.center : PUNCH.lead}px` }}>
                {v.groups.map((g, i) => (
                  <Group key={i} g={g} cls={`tg${i < v.letter || v.state === 'done' ? ' tg-spoken' : ''}${live && i === v.letter ? ' tg-live' : ''}`} />
                ))}
              </ol>
            </div>
          </div>
          <div className="station-status">
            <span className="station-lamp" />
            <p className="status-line" data-state-line="idle"><span className="status-legend">IDLE</span> <span className="status-copy">TYPE A MESSAGE. THE TAPE PUNCHES AS YOU GO.</span></p>
            <p className="status-line" data-state-line="broadcasting"><span className="status-legend">SENDING</span> <span className="status-copy">YOUR FLASHLIGHT IS SENDING THE MESSAGE.</span></p>
            <p className="status-line" data-state-line="done"><span className="status-legend">DONE</span> <span className="status-copy">THE RUN IS OVER. THE TAPE KEEPS THE MESSAGE.</span></p>
            <p className="status-progress" data-state-progress="broadcasting">MARK {v.mark} OF {v.marks}</p>
          </div>
        </section>
        <section className="bay" data-id="corridor">
          <div className="zone" data-zone="standby"><span className="zone-lamp" /><p className="zone-legend">STANDBY</p><p className="zone-line">INSTRUMENT ARMED. MESSAGE SET.</p></div>
          <div className="zone" data-zone="caution"><span className="zone-lamp" /><p className="zone-legend">CAUTION</p><p className="zone-line">THE LIGHT IS ABOUT TO SPEAK.</p></div>
          <div className="zone" data-zone="go"><span className="zone-lamp" /><p className="zone-legend">GO</p><p className="zone-line">SENDING NOW.</p></div>
        </section>
        <div className="control-deck">
          <Dock right={<><span className="dock-name">SENDING</span><span className="dock-meta">{v.wpm} WPM</span></>} />
          <section className="bay" data-id="transport">
            <div className="keys keys-cold"><span className="key key-primary key-broadcast">BROADCAST</span></div>
            <div className="keys keys-live">
              <span className="key key-stop">STOP</span><span className="key">PAUSE</span><span className="key">SWITCH TO SCREEN</span>
            </div>
            <p className="done-receipt"><span className="receipt-legend">SENT</span> <span className="receipt-detail">{v.sent}</span></p>
            <div className="keys keys-done"><span className="key key-primary">REPLAY</span><span className="key">COPY MORSE</span></div>
          </section>
        </div>
      </main>
    </Screen>
  );
}

export interface ReceiverView {
  state: 'receive-armed' | 'receive-active' | 'receive-done';
  meter: 'silence' | 'decoding';
  groups: TapeGroup[];
  heard: number;
  liveMarks: string;
  text: string;
  lamp: boolean;
}

export function ReceiverScreen({ v }: { v: ReceiverView }) {
  const shift = rxShift(v.groups, v.heard, v.liveMarks);
  return (
    <Screen attrs={{ 'data-state': v.state, 'data-mode': 'receive', 'data-meter': v.meter }}>
      <Nameplate mode="receive" />
      <main className="deck">
        <section className="bay bay-station" data-id="station">
          <div className="tape-window">
            <div className="tape-inset">
              <Head />
              <ol className="tape-strip tape-rx" style={{ ['--strip-shift' as string]: `${shift}px` }}>
                {v.groups.slice(0, v.heard).map((g, i) => <Group key={i} g={g} cls="tg tg-spoken" />)}
                {v.liveMarks && v.groups[v.heard] && <Group g={v.groups[v.heard]} cls="tg tg-live" marks={v.liveMarks} />}
              </ol>
            </div>
          </div>
          <div className="station-status">
            <span className="station-lamp" />
            <p className="status-line" data-receive-line="receive-armed"><span className="status-legend">LISTENING</span> <span className="status-copy">CAMERA ON. AIM AT THE FLASHING LIGHT.</span></p>
            <p className="status-line" data-receive-line="receive-active"><span className="status-legend">RECEIVING</span> <span className="status-copy">LIGHT SPEAKS. THE TAPE PUNCHES WHAT IT HEARS.</span></p>
            <p className="status-line" data-receive-line="receive-done"><span className="status-legend">HEARD</span> <span className="status-copy">THE MESSAGE STANDS ON THE TAPE.</span></p>
          </div>
        </section>
        <section className="bay bay-eye" data-id="eye">
          <div className="aperture" data-rx-camera="on">
            {/* What the camera sees: the sender phone, its flashlight firing. */}
            <div className="aperture-video mapp-view" data-on={v.lamp || undefined}>
              <span className="mapp-view-phone"><i /></span>
            </div>
            <span className="aperture-shutter" />
          </div>
          <div className="meter">
            <p className="meter-line" data-meter-line="silence">HEARING NOTHING</p>
            <p className="meter-line" data-meter-line="decoding">HEARING LIGHT</p>
            <p className="meter-hint" data-meter-hint="silence">Aim at the sender. Get closer. Dim the room.</p>
          </div>
        </section>
        <section data-id="received-message">
          <div className="transcript-head">
            <h2>RECEIVED MESSAGE</h2>
            <div className="transcript-actions"><span className="key" aria-disabled={!v.text || undefined}>COPY</span></div>
          </div>
          <div className="transcript-scroll" data-id="received-text" data-empty={v.text ? undefined : 'true'}>
            {v.text || 'Decoded letters appear here.'}
          </div>
          <p className="receive-done-offer">Letters appear as the light is decoded.</p>
        </section>
        <div className="control-deck">
          <Dock right={<span className="dock-name">LOG</span>} />
          <section className="bay" data-id="transport">
            <div className="keys keys-receive-live"><span className="key key-stop">STOP LISTENING</span></div>
            <div className="keys keys-receive-done"><span className="key key-primary">LISTEN AGAIN</span></div>
          </section>
        </div>
      </main>
    </Screen>
  );
}
